// Package uuid generates UUID version 7 identifiers.
//
// v7 is used instead of v4 for one reason: it is time-ordered, so inserts stay
// near the end of a B-tree index instead of scattering across it. The ID is
// generated by the application (not the database) so it is known before INSERT,
// which idempotency keys and event publishing both need (PRD.md §8.4).
package uuid

import (
	"crypto/rand"
	"encoding/hex"
	"time"
)

// New returns a UUIDv7 string in canonical 8-4-4-4-12 form.
func New() string {
	var b [16]byte

	// 48-bit Unix milliseconds, big-endian.
	ms := uint64(time.Now().UnixMilli())
	b[0] = byte(ms >> 40)
	b[1] = byte(ms >> 32)
	b[2] = byte(ms >> 24)
	b[3] = byte(ms >> 16)
	b[4] = byte(ms >> 8)
	b[5] = byte(ms)

	// 74 bits of randomness (10 bytes), then set the version and variant bits.
	if _, err := rand.Read(b[6:]); err != nil {
		// A failure here means the OS entropy source is broken; falling back to
		// the timestamp alone would produce collisions, so panic is the honest
		// response. This is unreachable on any supported platform.
		panic("uuid: entropy source unavailable: " + err.Error())
	}

	b[6] = (b[6] & 0x0f) | 0x70 // version 7
	b[8] = (b[8] & 0x3f) | 0x80 // variant RFC 4122

	return encode(b)
}

func encode(b [16]byte) string {
	var out [36]byte
	hex.Encode(out[0:8], b[0:4])
	out[8] = '-'
	hex.Encode(out[9:13], b[4:6])
	out[13] = '-'
	hex.Encode(out[14:18], b[6:8])
	out[18] = '-'
	hex.Encode(out[19:23], b[8:10])
	out[23] = '-'
	hex.Encode(out[24:36], b[10:16])
	return string(out[:])
}

// IsValid reports whether s is a canonical 8-4-4-4-12 UUID.
//
// It exists so a handler can reject a malformed identifier as a validation
// error instead of passing it to PostgreSQL, where an invalid uuid literal is a
// driver error and surfaces as a 500.
func IsValid(s string) bool {
	if len(s) != 36 {
		return false
	}
	for i, r := range s {
		switch i {
		case 8, 13, 18, 23:
			if r != '-' {
				return false
			}
		default:
			isHex := (r >= '0' && r <= '9') || (r >= 'a' && r <= 'f') || (r >= 'A' && r <= 'F')
			if !isHex {
				return false
			}
		}
	}
	return true
}
